describe('Reorder list items by drag and drop', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="list-container"]').should('be.visible');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
  });

  it('should reorder list items when dragging and dropping', () => {
    // Get initial order of items
    cy.get('[data-testid="list-item"]').then(($items) => {
      const initialOrder = Array.from($items).map(item => item.textContent);

      // Drag first item to third position
      cy.get('[data-testid="list-item"]').eq(0).trigger('mousedown', { button: 0 });
      cy.get('[data-testid="list-item"]').eq(2).trigger('dragover');
      cy.get('[data-testid="list-item"]').eq(2).trigger('drop');
      cy.get('[data-testid="list-item"]').eq(0).trigger('mouseup');

      // Verify order has changed
      cy.get('[data-testid="list-item"]').then(($reorderedItems) => {
        const newOrder = Array.from($reorderedItems).map(item => item.textContent);
        expect(newOrder).not.to.deep.equal(initialOrder);
      });
    });

    // Verify list items are still visible and intact
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="list-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
  });

  it('should handle drag and drop with keyboard accessibility', () => {
    // Focus on first list item
    cy.get('[data-testid="list-item"]').eq(0).focus();

    // Verify item is focused
    cy.get('[data-testid="list-item"]').eq(0).should('have.focus');

    // Simulate drag with keyboard (Space to grab, Arrow keys to move, Enter to drop)
    cy.get('[data-testid="list-item"]').eq(0).type(' ');
    cy.get('[data-testid="list-item"]').eq(0).type('{downarrow}{downarrow}');
    cy.get('[data-testid="list-item"]').eq(0).type('{enter}');

    // Verify item was reordered
    cy.get('[data-testid="list-item"]').eq(0).should('exist');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
  });

  it('should maintain list integrity when dragging to same position', () => {
    cy.get('[data-testid="list-item"]').then(($items) => {
      const initialOrder = Array.from($items).map(item => item.textContent);

      // Drag item to same position
      cy.get('[data-testid="list-item"]').eq(1).trigger('mousedown', { button: 0 });
      cy.get('[data-testid="list-item"]').eq(1).trigger('dragover');
      cy.get('[data-testid="list-item"]').eq(1).trigger('drop');
      cy.get('[data-testid="list-item"]').eq(1).trigger('mouseup');

      // Verify order remains the same
      cy.get('[data-testid="list-item"]').then(($reorderedItems) => {
        const newOrder = Array.from($reorderedItems).map(item => item.textContent);
        expect(newOrder).to.deep.equal(initialOrder);
      });
    });
  });

  it('should persist reordered list after page reload', () => {
    // Perform drag and drop
    cy.get('[data-testid="list-item"]').eq(0).trigger('mousedown', { button: 0 });
    cy.get('[data-testid="list-item"]').eq(2).trigger('dragover');
    cy.get('[data-testid="list-item"]').eq(2).trigger('drop');
    cy.get('[data-testid="list-item"]').eq(0).trigger('mouseup');

    // Get reordered state
    cy.get('[data-testid="list-item"]').then(($items) => {
      const reorderedList = Array.from($items).map(item => item.textContent);

      // Reload page
      cy.reload();

      // Verify order is persisted
      cy.get('[data-testid="list-item"]').then(($reloadedItems) => {
        const reloadedList = Array.from($reloadedItems).map(item => item.textContent);
        expect(reloadedList).to.deep.equal(reorderedList);
      });
    });
  });

  it('should handle edge case of dragging last item to first position', () => {
    cy.get('[data-testid="list-item"]').then(($items) => {
      const lastIndex = $items.length - 1;
      const lastItemText = $items[lastIndex].textContent;

      // Drag last item to first position
      cy.get('[data-testid="list-item"]').eq(lastIndex).trigger('mousedown', { button: 0 });
      cy.get('[data-testid="list-item"]').eq(0).trigger('dragover');
      cy.get('[data-testid="list-item"]').eq(0).trigger('drop');
      cy.get('[data-testid="list-item"]').eq(lastIndex).trigger('mouseup');

      // Verify last item is now first
      cy.get('[data-testid="list-item"]').eq(0).should('contain', lastItemText);
    });
  });
});
